export const clamp=(x,a,b)=>Math.max(a,Math.min(b,x));
export const dist=(a,b)=>Math.hypot(a[0]-b[0],a[1]-b[1]);
export const area=p=>Math.abs(p.reduce((s,a,i)=>{let b=p[(i+1)%p.length];return s+a[0]*b[1]-b[0]*a[1]},0))/2;
export function angle(a,b,c){let u=[a[0]-b[0],a[1]-b[1]],v=[c[0]-b[0],c[1]-b[1]];return Math.acos(clamp((u[0]*v[0]+u[1]*v[1])/(Math.hypot(...u)*Math.hypot(...v)),-1,1))*180/Math.PI}
export function polygonAngles(p){let signed=p.reduce((s,a,i)=>{let b=p[(i+1)%p.length];return s+a[0]*b[1]-b[0]*a[1]},0),sign=Math.sign(signed);return p.map((b,i)=>{let a=p[(i+p.length-1)%p.length],c=p[(i+1)%p.length],cross=(b[0]-a[0])*(c[1]-b[1])-(b[1]-a[1])*(c[0]-b[0]);let t=angle(a,b,c);return cross*sign<0?360-t:t})}
export function heron(a,b,c){let s=(a+b+c)/2;return {s,valid:a>0&&b>0&&c>0&&a+b>c+1e-9&&b+c>a+1e-9&&c+a>b+1e-9,area:Math.sqrt(Math.max(0,s*(s-a)*(s-b)*(s-c)))}}
export function roots(a,b,c,d){if(Math.abs(a)<1e-10){if(Math.abs(b)<1e-10)return Math.abs(c)<1e-10?[]:[-d/c];let D=c*c-4*b*d;return D<0?[]:D===0?[-c/(2*b)]:[(-c-Math.sqrt(D))/(2*b),(-c+Math.sqrt(D))/(2*b)].sort((x,y)=>x-y)}let critical=[];
let D=4*b*b-12*a*c;critical=D>=0?[(-2*b-Math.sqrt(D))/(6*a),(-2*b+Math.sqrt(D))/(6*a)]:[];let bound=1+Math.max(Math.abs(b/a),Math.abs(c/a),Math.abs(d/a)),xs=[-bound,...critical.filter(x=>x>-bound&&x<bound).sort((x,y)=>x-y),bound],f=x=>((a*x+b)*x+c)*x+d,out=[];for(let x of xs)if(Math.abs(f(x))<1e-7)out.push(x);for(let i=1;i<xs.length;i++){let l=xs[i-1],r=xs[i];if(f(l)*f(r)>=0)continue;for(let k=0;k<70;k++){let m=(l+r)/2;if(f(l)*f(m)<=0)r=m;else l=m}out.push((l+r)/2)}return [...new Set(out.map(x=>Math.round(x*1e7)/1e7))].sort((x,y)=>x-y)}
export function intersection(a,b,c,A,B,C){let D=a*B-A*b;if(Math.abs(D)<1e-9)return {type:Math.abs(a*C-A*c)<1e-9&&Math.abs(b*C-B*c)<1e-9?'coincident':'parallel'};return {type:'point',x:(b*C-B*c)/D,y:(c*A-C*a)/D}}
export function statistics(rows){let data=rows.filter(r=>Number.isFinite(r[0])&&Number.isInteger(r[1])&&r[1]>=0).sort((a,b)=>a[0]-b[0]),n=data.reduce((s,r)=>s+r[1],0);if(!n)return null;let at=k=>{let count=0;for(let [x,f]of data){count+=f;if(count>k)return x}};let max=Math.max(...data.map(r=>r[1]));return {n,mean:data.reduce((s,[x,f])=>s+x*f,0)/n,median:(at(Math.floor((n-1)/2))+at(Math.floor(n/2)))/2,modes:data.filter(r=>r[1]===max).map(r=>r[0])}}
export function solidMetrics(shape,x,y,z){if(shape==='cuboid')return {tsa:2*(x*y+y*z+z*x),volume:x*y*z,formula:`TSA = 2(lb + bh + hl) = 2(${x} × ${y} + ${y} × ${z} + ${z} × ${x})`,vformula:`V = lbh = ${x} × ${y} × ${z}`};if(shape==='sphere')return {tsa:4*Math.PI*x*x,volume:4*Math.PI*x**3/3,formula:`TSA = 4πr² = 4π × ${x}²`,vformula:`V = 4πr³/3 = 4π × ${x}³/3`};if(shape==='cylinder')return {tsa:2*Math.PI*x*(x+y),volume:Math.PI*x*x*y,formula:`TSA = 2πr(r+h) = 2π × ${x}(${x}+${y})`,vformula:`V = πr²h = π × ${x}² × ${y}`};let l=Math.hypot(x,y);return {tsa:Math.PI*x*(x+l),volume:Math.PI*x*x*y/3,slant:l,formula:`l = √(${x}²+${y}²) = ${l.toFixed(3)}; TSA = πr(r+l)`,vformula:`V = πr²h/3 = π × ${x}² × ${y}/3`}}
